preConditionHook:
// UpperBandTouchBarBreak (Brian's notes ON-64-b, #64). upT is the most
// recent bar in 1 .. maxWaitBars whose high touched the upper band (el_ge).
// Long on the FIRST close above high[upT] since that bar, provided no bar since
// (1 .. upT - 1, and this bar) touched the lower band. Short mirrors: the most
// recent lower-band touch dnT, the first close below low[dnT], invalidated by
// an upper-band touch. A lower touch ON bar upT itself does not invalidate;
// a bar touching both bands at bar 0 fires neither side.
// The bands are BollingerBandCross's construction, open-coded at each offset
// ii so a past bar's band is computed from price as it stood on that bar (EL's
// BollingerBand is fresh per bar; reading a stored band variable at [ii]
// would compare against its zero fill during warm-up): Average(close, length)
// summed NEWEST-FIRST, POPULATION StdDev, upper = avg + numDevs x sd, lower =
// avg + (-numDevs) x sd. `bollingerband` VERIFIED; do not reorder the loops.
upT = 0;
dnT = 0;
touchUp0 = false;
touchDn0 = false;
for (int ii = 0; ii <= (int)maxWaitBars; ++ii) {
    bbAvg = 0.0;
    for (int jj = 0; jj < (int)length; ++jj) {
        bbAvg += close[ii + jj];
    }
    bbAvg /= (int)length;
    bbSd = 0.0;
    for (int jj = 0; jj < (int)length; ++jj) {
        bbDev = close[ii + jj] - bbAvg;
        bbSd += bbDev * bbDev;
    }
    bbSd = std::sqrt(bbSd / (int)length);
    upperBand = bbAvg + numDevs * bbSd;
    lowerBand = bbAvg + (-numDevs) * bbSd;
    touchUp = el_ge(high[ii], upperBand);
    touchDn = el_le(low[ii], lowerBand);
    if (ii == 0) {
        touchUp0 = touchUp;
        touchDn0 = touchDn;
    } else {
        if (upT == 0 && touchUp) upT = ii;
        if (dnT == 0 && touchDn) dnT = ii;
    }
}
// The most recent opposite touch is the only one that can lie in 1 .. T - 1.
longOk = upT > 0 && (dnT == 0 || dnT >= upT) && !touchDn0;
for (int jj = 1; jj < upT; ++jj) {
    if (el_gt(close[jj], high[upT])) longOk = false;
}
shortOk = dnT > 0 && (upT == 0 || upT >= dnT) && !touchUp0;
for (int jj = 1; jj < dnT; ++jj) {
    if (el_lt(close[jj], low[dnT])) shortOk = false;
}
